<template>
<div>
    <v-main>
    <v-card
    class="mx-auto my-12 mx-4"
    max-width="374"
    >
    <v-img
      height="250"
      :src="photo"
    ></v-img>

    <v-card-title>
        {{ $t('update.title') }}
    </v-card-title>

    <v-container>
        <v-text-field
            v-model="title"
            required
            :label="$t('update.name')"
        >
        </v-text-field>
          <v-switch
        hide-details
        v-model="isPlus18"
        color="red"
        :label="plus18Label"
        ></v-switch>
          <v-combobox
          v-model="category"
          :items="categories"
          :label="$t('update.category')"
          chips>
          </v-combobox>
         <v-combobox
          v-model="select"
          :items="items"
          :label="$t('update.tags')"
          multiple
          chips
    ></v-combobox>
    </v-container>

    <v-divider class="mx-4"></v-divider>

    <v-card-actions>
      <v-spacer></v-spacer>
      <v-btn
        :loading="updating"
        color=" teal lighten-3"
        @click="updateSticker"
      >
        {{ $t('update.submit') }}
      </v-btn>
    </v-card-actions>
      <v-snackbar
      v-model="hasSaved"
      :timeout="1500"
      absolute
      bottom
      left
    >
      {{notification}}
    </v-snackbar>
  </v-card>
    </v-main>
</div>
</template>

<script>
import { db } from '../firebase';

export default {
  data() {
    return {
      isPlus18: false,
      notification: '',
      photo: '',
      db,
      category: '',
      categories: [],
      title: '',
      updating: false,
      hasSaved: false,
      select: [],
      items: [
      ],
    };
  },
  computed: {
    plus18Label() {
      const answer = this.$t(this.isPlus18 ? 'update.plus18Yes' : 'update.plus18No');
      return this.$t('update.plus18', { answer });
    },
    stickerId() {
      return this.$route.params.stickerId;
    },
  },
  methods: {
    async updateSticker() {
      this.updating = true;
      if (this.isPlus18) {
        this.select.push('+18');
      } else {
        this.select = this.select.filter((x) => x !== '+18');
      }
      db.collection('stickers').doc(this.stickerId).update({
        tags: this.select.map((element) => element.toLowerCase()),
        stickerName: this.title,
        category: this.category,
        isPlus18: this.isPlus18,
      }).then(() => {
        db.collection('categories').doc(this.category).set({ categoryName: this.category, categoryImageURL: null });
        this.notification = this.$t('update.saved');
        this.updating = false;
        this.hasSaved = true;
      })
        .catch(() => {
          this.notification = this.$t('update.failed');
          this.updating = false;
          this.hasSaved = true;
        });
    },
  },
  async created() {
    await db.collection('categories').get().then((querySnapshot) => {
      const documents = querySnapshot.docs.map((doc) => doc.data().categoryName);
      this.categories = documents;
      console.log(documents);
    });

    const stickerToUpdate = await db.collection('stickers').doc(this.stickerId).get();
    const idOfDoc = (stickerToUpdate.id);
    console.log(idOfDoc);
    if (!stickerToUpdate.exists) {
      this.$router.push({ path: '/notfound' });
    } else {
      const sticker = stickerToUpdate.data();
      console.log(sticker);
      this.category = sticker.category;
      this.title = sticker.stickerName;
      this.items = sticker.tags;
      this.select = sticker.tags;
      this.photo = sticker.stickerImageURL;

      if (this.select.some((x) => x === '+18')) {
        this.isPlus18 = true;
      }
    }
  },
};
</script>

