const SUPPORTED = Object.keys(messages);
const STORAGE_KEY = 'stickerhub-lang';

function remember(locale) {
  try {
    window.localStorage.setItem(STORAGE_KEY, locale);
  } catch (e) {
    // Not remembered; the choice still applies to this visit.
  }
}

// ?lang= wins (so a link can pick the language), then the last choice, then the browser.
function initialLocale() {
  const fromUrl = new URLSearchParams(window.location.search).get('lang');
  if (SUPPORTED.includes(fromUrl)) {
    remember(fromUrl);
    return fromUrl;
  }
  try {
    const saved = window.localStorage.getItem(STORAGE_KEY);
    if (SUPPORTED.includes(saved)) return saved;
  } catch (e) {
    // Storage can be blocked; fall through to the browser language.
  }
  return (navigator.languages || [navigator.language]).some((l) => /^tr\b/i.test(l || '')) ? 'tr' : 'en';
}

const i18n = new VueI18n({ locale: initialLocale(), fallbackLocale: 'en', messages });

// Uppercase a message for labels styled in caps. Turkish casing turns the English loanword
// "sticker" into "STİCKER", so that word keeps its English capitals.
Vue.prototype.$caps = function caps(key) {
  return this.$t(key).toLocaleUpperCase(this.$i18n.locale).replace(/STİCKER/g, 'STICKER');
};

function applyLocale(locale) {
  document.documentElement.lang = locale;
  document.title = i18n.t('meta.title');
}

export function setLocale(locale) {
  i18n.locale = locale;
  applyLocale(locale);
  remember(locale);
}

applyLocale(i18n.locale);

export default i18n;
